 "content": "def transform(grid):
    """Restore zeroed cells in a cyclic grid with one repeated diagonal value."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if not rows or not cols:
        return [row[:] for row in grid]

    # The palette is the consecutive cycle 1..k. The first row starts at
    # its first visible color; subsequent rows start at its successor.
    palette = sorted({v for row in grid for v in row if v != 0})
    k = len(palette)
    if not k:
        return [row[:] for row in grid]
    start0 = grid[0][0]
    if start0 == 0:
        # Find the first nonzero in row 0 if its leading part is masked.
        start0 = next((v for v in grid[0] if v), palette[0])
    cycle = list(range(1, k + 1))

    def successor(v):
        return cycle[(cycle.index(v) + 1) % k]

    starts = [start0] + [successor(start0)] * max(0, rows - 1)
    out = [row[:] for row in grid]
    for r in range(rows):
        start = starts[r]
        base_index = cycle.index(start)
        for c in range(cols):
            if r == 0:
                idx = c
            elif c < r:
                idx = c
            else:
                idx = c - 1
            value = cycle[(base_index + idx) % k]
            if out[r][c] == 0:
                out[r][c] = value
    return out
